"""Lexical boundary for jq source programs.

The lexer deliberately has no runtime dependencies beyond the standard library.  It
returns immutable tokens so the parser can make syntax decisions without knowing
anything about evaluation.
"""

from __future__ import annotations

from dataclasses import dataclass
import re


@dataclass(frozen=True)
class Token:
    kind: str
    value: str
    position: int


class LexError(ValueError):
    """Raised when source cannot be converted into jq tokens."""


_TOKEN_RE = re.compile(
    r"(?P<space>\s+)|(?P<comment>#[^\n]*)|(?P<number>-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?)|"
    r"(?P<string>\"(?:\\.|[^\"\\])*\")|(?P<operator>\|=|//|==|!=|<=|>=|\+=|-=|\*=|/=|\|)|"
    r"(?P<punct>[.,:;()\[\]{}?+*/=<>$@])|(?P<word>[A-Za-z_][A-Za-z0-9_]*)"
)


def tokenize(source: str) -> list[Token]:
    """Tokenize *source*, raising :class:`LexError` on an unknown character."""
    tokens: list[Token] = []
    position = 0
    while position < len(source):
        match = _TOKEN_RE.match(source, position)
        if match is None:
            raise LexError(f"unexpected character at position {position}")
        kind = match.lastgroup
        assert kind is not None
        value = match.group(kind)
        position = match.end()
        if kind in {"space", "comment"}:
            continue
        tokens.append(Token(kind, value, match.start()))
    tokens.append(Token("eof", "", len(source)))
    return tokens

