"""Precedence-aware front end for the executable jq architecture."""

from __future__ import annotations

from dataclasses import dataclass
import json

from jq_lexer import Token, tokenize


class ParseError(ValueError):
    """Raised for syntax and static errors."""


@dataclass(frozen=True)
class Node:
    kind: str
    value: object = None
    children: tuple["Node", ...] = ()


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.index = 0

    def current(self) -> Token:
        return self.tokens[self.index]

    def take(self) -> Token:
        token = self.current()
        self.index += 1
        return token

    def expression(self) -> Node:
        left = self.term()
        if self.current().value in {"|", ","}:
            operator = self.take().value
            right = self.expression()
            return Node(operator, children=(left, right))
        return left

    def term(self) -> Node:
        token = self.take()
        if token.kind == "eof":
            raise ParseError("expected filter")
        if token.value == ".":
            if self.current().value == "[":
                self.take()
                if self.current().value != "]":
                    raise ParseError("only empty iterator syntax is supported by this boundary")
                self.take()
                return Node("iterate")
            return Node("identity")
        if token.kind == "number":
            return Node("literal", json.loads(token.value))
        if token.kind == "string":
            return Node("literal", json.loads(token.value))
        if token.kind == "word" and token.value in {"true", "false", "null", "empty"}:
            return Node(token.value)
        if token.value == "(":
            value = self.expression()
            if self.take().value != ")":
                raise ParseError("expected closing parenthesis")
            return value
        raise ParseError(f"unexpected token at position {token.position}")


def parse(source: str) -> Node:
    """Parse jq source into an AST suitable for :func:`jq_runtime.evaluate`."""
    parser = Parser(tokenize(source))
    tree = parser.expression()
    if parser.current().kind != "eof":
        raise ParseError(f"unexpected token at position {parser.current().position}")
    return tree

